package argon2id

func Blake2b(out, in []byte)          { blake2b(out, in) }
func HPrime(out, in []byte)           { hPrime(out, in) }
func CompressBlock(out, x, y *Block)  { processBlock(out, x, y, false) }
func Permute(b *Block)                { permute(b) }

func Hash(password, salt, secret, associatedData []byte, parallelism, memory, iterations, tagSize uint32) ([]byte, error) {
	return Argon2id(password, salt, secret, associatedData, parallelism, memory, iterations, tagSize)
}
