### 3.2 `argon2id.go`

```go
// Package argon2id implements Argon2id per RFC 9106 with only the Go standard library.
package argon2id

import (
	"encoding/binary"
	"errors"
	"math"
)

const Version = 0x13

const (
	blockWords  = 128
	blockBytes  = 1024
	syncPoints  = 4
	argon2idVal = 2
)

type Block [blockWords]uint64

type Params struct {
	Parallelism uint32 // p, 1 <= p <= 2^24-1
	Memory      uint32 // m, KiB, >= 8*p
	Iterations  uint32 // t, >= 1
	TagSize     uint32 // T, >= 4
}

var (
	ErrTimeTooSmall   = errors.New("argon2id: iterations t must be >= 1")
	ErrMemoryTooSmall = errors.New("argon2id: memory m must be >= 8*parallelism")
	ErrLanesTooFew    = errors.New("argon2id: parallelism p must be >= 1")
	ErrLanesTooMany   = errors.New("argon2id: parallelism p must be <= 2^24-1")
	ErrTagTooShort    = errors.New("argon2id: tag length must be >= 4")
	ErrSaltTooShort   = errors.New("argon2id: salt must be >= 8 bytes")
)

func DeriveKey(password, salt, secret, associatedData []byte, params Params) ([]byte, error) {
	if err := params.validate(); err != nil {
		return nil, err
	}
	if len(salt) < 8 {
		return nil, ErrSaltTooShort
	}
	if uint64(len(password)) > math.MaxUint32 || uint64(len(salt)) > math.MaxUint32 ||
		uint64(len(secret)) > math.MaxUint32 || uint64(len(associatedData)) > math.MaxUint32 {
		return nil, errors.New("argon2id: input too long")
	}

	p, m, t, tagSize := params.Parallelism, params.Memory, params.Iterations, params.TagSize

	h0 := initialHash(password, salt, secret, associatedData, p, m, t, tagSize)

	memBlocks := (m / (syncPoints * p)) * (syncPoints * p) // m' >= 8p
	laneLength := memBlocks / p
	segmentLength := laneLength / syncPoints

	mem := make([]Block, memBlocks)
	initBlocks(mem, &h0, p, laneLength)

	for pass := uint32(0); pass < t; pass++ {
		for slice := uint32(0); slice < syncPoints; slice++ {
			for lane := uint32(0); lane < p; lane++ {
				fillSegment(mem, pass, lane, slice, p, laneLength, segmentLength, t, memBlocks)
			}
		}
	}
	return extractTag(mem, p, laneLength, tagSize), nil
}

func Argon2id(password, salt, secret, associatedData []byte, parallelism, memory, iterations, tagSize uint32) ([]byte, error) {
	return DeriveKey(password, salt, secret, associatedData, Params{parallelism, memory, iterations, tagSize})
}

func IDKey(password, salt []byte, time, memory uint32, threads uint8, keyLen uint32) ([]byte, error) {
	return DeriveKey(password, salt, nil, nil, Params{uint32(threads), memory, time, keyLen})
}

func (p Params) validate() error {
	if p.Iterations < 1 {
		return ErrTimeTooSmall
	}
	if p.Parallelism < 1 {
		return ErrLanesTooFew
	}
	if p.Parallelism > 0xFFFFFF {
		return ErrLanesTooMany
	}
	if uint64(p.Memory) < uint64(8)*uint64(p.Parallelism) {
		return ErrMemoryTooSmall
	}
	if p.TagSize < 4 {
		return ErrTagTooShort
	}
	return nil
}

func initialHash(password, salt, secret, ad []byte, p, m, t, tagSize uint32) [72]byte {
	const header = 6*4 + 4*4
	total := header + len(password) + len(salt) + len(secret) + len(ad)

	var stack [1024]byte
	var buf []byte
	if total <= len(stack) {
		buf = stack[:0]
	} else {
		buf = make([]byte, 0, total)
	}
	var w [4]byte
	put := func(v uint32) {
		binary.LittleEndian.PutUint32(w[:], v)
		buf = append(buf, w[:]...)
	}
	put(p)
	put(tagSize)
	put(m)
	put(t)
	put(Version)
	put(argon2idVal)
	for _, b := range [][]byte{password, salt, secret, ad} {
		put(uint32(len(b)))
		buf = append(buf, b...)
	}
	var h0 [72]byte
	blake2b(h0[:64], buf)
	return h0
}

func initBlocks(mem []Block, h0 *[72]byte, p, laneLength uint32) {
	var raw [blockBytes]byte
	for lane := uint32(0); lane < p; lane++ {
		base := lane * laneLength
		for idx := uint32(0); idx < 2; idx++ {
			binary.LittleEndian.PutUint32(h0[64:68], idx)
			binary.LittleEndian.PutUint32(h0[68:72], lane)
			hPrime(raw[:], h0[:])
			for i := 0; i < blockWords; i++ {
				mem[base+idx][i] = binary.LittleEndian.Uint64(raw[i*8:])
			}
		}
	}
}

func fillSegment(mem []Block, pass, lane, slice, lanes, laneLength, segmentLength, passes, memBlocks uint32) {
	dataIndependent := pass == 0 && slice < 2

	var addressBlock, inputBlock, zero Block
	if dataIndependent {
		inputBlock[0] = uint64(pass)
		inputBlock[1] = uint64(lane)
		inputBlock[2] = uint64(slice)
		inputBlock[3] = uint64(memBlocks)
		inputBlock[4] = uint64(passes)
		inputBlock[5] = argon2idVal
	}
	index := uint32(0)
	if pass == 0 && slice == 0 {
		index = 2
		if dataIndependent {
			inputBlock[6]++
			processBlock(&addressBlock, &inputBlock, &zero, false)
			processBlock(&addressBlock, &addressBlock, &zero, false)
		}
	}
	offset := lane*laneLength + slice*segmentLength + index
	for index < segmentLength {
		prev := offset - 1
		if index == 0 && slice == 0 {
			prev += laneLength
		}
		var rand uint64
		if dataIndependent {
			if index%blockWords == 0 {
				inputBlock[6]++
				processBlock(&addressBlock, &inputBlock, &zero, false)
				processBlock(&addressBlock, &addressBlock, &zero, false)
			}
			rand = addressBlock[index%blockWords]
		} else {
			rand = mem[prev][0]
		}
		refLane := uint32(rand>>32) % lanes
		if pass == 0 && slice == 0 {
			refLane = lane
		}
		refIndex := indexAlpha(uint32(rand&0xFFFFFFFF), refLane, lane, laneLength, segmentLength, pass, slice, index)
		processBlock(&mem[offset], &mem[prev], &mem[refLane*laneLength+refIndex], pass != 0)
		index++
		offset++
	}
}

func indexAlpha(rand, refLane, lane, laneLength, segmentLength, pass, slice, index uint32) uint32 {
	sameLane := refLane == lane
	var areaSize, startPos uint32
	if pass == 0 {
		if slice == 0 {
			areaSize = index - 1
		} else if sameLane {
			areaSize = slice*segmentLength + index - 1
		} else if index == 0 {
			areaSize = slice*segmentLength - 1
		} else {
			areaSize = slice * segmentLength
		}
	} else {
		if sameLane {
			areaSize = laneLength - segmentLength + index - 1
		} else if index == 0 {
			areaSize = laneLength - segmentLength - 1
		} else {
			areaSize = laneLength - segmentLength
		}
	}
	x := (uint64(rand) * uint64(rand)) >> 32
	rel := uint64(areaSize) - 1 - ((uint64(areaSize) * x) >> 32)
	if pass != 0 {
		if slice == syncPoints-1 {
			startPos = 0
		} else {
			startPos = (slice + 1) * segmentLength
		}
	}
	return (startPos + uint32(rel)) % laneLength
}

func processBlock(out, in1, in2 *Block, withXor bool) {
	var t Block
	for i := range t {
		t[i] = in1[i] ^ in2[i]
	}
	permute(&t)
	if withXor {
		for i := range t {
			out[i] ^= in1[i] ^ in2[i] ^ t[i]
		}
		return
	}
	for i := range t {
		out[i] = in1[i] ^ in2[i] ^ t[i]
	}
}

func permute(b *Block) {
	for i := 0; i < blockWords; i += 16 {
		blamkaRound(b,
			i+0, i+1, i+2, i+3, i+4, i+5, i+6, i+7,
			i+8, i+9, i+10, i+11, i+12, i+13, i+14, i+15)
	}
	for i := 0; i < 16; i += 2 {
		blamkaRound(b,
			i, i+1, 16+i, 16+i+1, 32+i, 32+i+1, 48+i, 48+i+1,
			64+i, 64+i+1, 80+i, 80+i+1, 96+i, 96+i+1, 112+i, 112+i+1)
	}
}

func blamkaRound(v *Block, i0, i1, i2, i3, i4, i5, i6, i7, i8, i9, i10, i11, i12, i13, i14, i15 int) {
	blamkaG(v, i0, i4, i8, i12)
	blamkaG(v, i1, i5, i9, i13)
	blamkaG(v, i2, i6, i10, i14)
	blamkaG(v, i3, i7, i11, i15)
	blamkaG(v, i0, i5, i10, i15)
	blamkaG(v, i1, i6, i11, i12)
	blamkaG(v, i2, i7, i8, i13)
	blamkaG(v, i3, i4, i9, i14)
}

func blamkaG(v *Block, a, b, c, d int) {
	va, vb, vc, vd := v[a], v[b], v[c], v[d]
	va += vb + 2*uint64(uint32(va))*uint64(uint32(vb))
	vd = rotr64(vd^va, 32)
	vc += vd + 2*uint64(uint32(vc))*uint64(uint32(vd))
	vb = rotr64(vb^vc, 24)
	va += vb + 2*uint64(uint32(va))*uint64(uint32(vb))
	vd = rotr64(vd^va, 16)
	vc += vd + 2*uint64(uint32(vc))*uint64(uint32(vd))
	vb = rotr64(vb^vc, 63)
	v[a], v[b], v[c], v[d] = va, vb, vc, vd
}

func extractTag(mem []Block, p, laneLength, tagSize uint32) []byte {
	last := (p-1)*laneLength + laneLength - 1
	for lane := uint32(0); lane < p-1; lane++ {
		src := mem[lane*laneLength+laneLength-1]
		for i := range mem[last] {
			mem[last][i] ^= src[i]
		}
	}
	var raw [blockBytes]byte
	for i, w := range mem[last] {
		binary.LittleEndian.PutUint64(raw[i*8:], w)
	}
	tag := make([]byte, tagSize)
	hPrime(tag, raw[:])
	return tag
}

func hPrime(out, in []byte) {
	t := uint32(len(out))
	var lenPrefix [4]byte
	binary.LittleEndian.PutUint32(lenPrefix[:], t)

	var stack [4 + 1024]byte
	var buf []byte
	if 4+len(in) <= len(stack) {
		buf = stack[:4+len(in)]
	} else {
		buf = make([]byte, 4+len(in))
	}
	copy(buf, lenPrefix[:])
	copy(buf[4:], in)

	if t <= 64 {
		blake2b(out, buf)
		return
	}
	v := blake2b512(buf)
	r := (t+31)/32 - 2
	off := uint32(0)
	for i := uint32(0); i < r; i++ {
		copy(out[off:], v[:32])
		off += 32
		if i == r-1 {
			blake2b(out[off:], v[:])
		} else {
			v = blake2b512(v[:])
		}
	}
}
